#include <algorithm>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;

class Item {
public:
    Item(int id, const string& name) : id(id), name(name) {}
    int id;
    string name;
    bool out = false;
};

int main() {
    vector<unique_ptr<Item>> shelf;
    shelf.push_back(make_unique<Item>(1, "鱼干小百科"));
    shelf.push_back(make_unique<Item>(2, "猫粮月报"));
    shelf.push_back(make_unique<Item>(3, "大肥鱼自传"));

    int id = 0;
    while (cin >> id) {
        bool ok = false;
        for (auto& it : shelf) {
            if (it->id != id) continue;
            if (!it->out) { it->out = true; ok = true; }
            break;
        }
        cout << (ok ? "办好了" : "办不了") << " " << id << endl;
    }

    int total = count_if(shelf.begin(), shelf.end(), [](const unique_ptr<Item>& p) { return p->out; });
    cout << "借出去 " << total << " 件" << endl;
    return 0;
}
